fn shell_command(input: &str, parsed: Option<&serde_json::Value>) -> String {
    parsed
        .and_then(|value| {
            ["command", "cmd"]
                .into_iter()
                .find_map(|key| value.get(key).and_then(serde_json::Value::as_str))
                .or_else(|| {
                    value
                        .get("metadata")
                        .and_then(|metadata| metadata.get("command"))
                        .and_then(serde_json::Value::as_str)
                })
                .map(str::to_owned)
        })
        .unwrap_or_else(|| {
            if parsed.is_some() || input.trim_start().starts_with('{') {
                String::new()
            } else {
                input.trim().to_owned()
            }
        })
}

fn tool_content_body(name: &str, parsed: Option<&serde_json::Value>) -> Option<String> {
    let lower = name.to_ascii_lowercase();
    if !matches!(
        lower.as_str(),
        "write"
            | "write_file"
            | "create_file"
            | "edit"
            | "str_replace"
            | "str_replace_editor"
            | "patch"
            | "apply_patch"
    ) {
        return None;
    }
    let object = parsed?.as_object()?;
    let field = |keys: &[&str]| {
        keys.iter()
            .find_map(|key| object.get(*key).and_then(serde_json::Value::as_str))
    };
    if let Some(content) = field(&["patch", "patchText", "patch_text", "diff"]) {
        return Some(content.to_owned());
    }
    if matches!(lower.as_str(), "write" | "write_file" | "create_file") {
        return field(&["content", "text"]).map(str::to_owned);
    }
    let mut diff = String::new();
    let decoded = object
        .get("edits")
        .and_then(serde_json::Value::as_str)
        .and_then(|edits| serde_json::from_str::<serde_json::Value>(edits).ok());
    if let Some(edits) = decoded
        .as_ref()
        .or_else(|| object.get("edits"))
        .and_then(serde_json::Value::as_array)
    {
        for edit in edits {
            append_tool_edit(&mut diff, edit);
        }
    } else {
        append_tool_edit(&mut diff, parsed?);
    }
    if diff.is_empty() {
        field(&["content", "newString", "new_string", "newText", "new_text"]).map(str::to_owned)
    } else {
        Some(diff)
    }
}

fn append_tool_edit(diff: &mut String, edit: &serde_json::Value) {
    let field = |keys: &[&str]| {
        keys.iter()
            .find_map(|key| edit.get(*key).and_then(serde_json::Value::as_str))
    };
    let old = field(&["oldString", "old_string", "oldText", "old_text"]);
    let new = field(&["newString", "new_string", "newText", "new_text"]);
    let (Some(old), Some(new)) = (old, new) else {
        return;
    };
    diff.push_str("@@\n");
    for (prefix, text) in [('-', old), ('+', new)] {
        for line in text.split_inclusive('\n') {
            diff.push(prefix);
            diff.push_str(line);
            if !line.ends_with('\n') {
                diff.push('\n');
            }
        }
    }
}

fn model_picker_filter_marker(color: Hsla, row_height: f32) -> impl IntoElement {
    div()
        .absolute()
        .right(px(4.0))
        .top(px((row_height - 20.0) / 2.0))
        .w(px(3.0))
        .h(px(20.0))
        .rounded_full()
        .bg(color)
}

fn style_auth_input(input: Input, tokens: ThemeTokens, focused: bool) -> Input {
    input
        .appearance(false)
        .bordered(false)
        .border_1()
        .rounded(px(6.0))
        .bg(tokens.pane_bg)
        .border_color(if focused {
            tokens.ring
        } else {
            tokens.card_border
        })
        .text_color(tokens.text_primary)
}

fn tool_paint_marker(id: Option<&str>, output: bool) -> Option<impl IntoElement> {
    let id = id
        .filter(|id| crate::stream_timing::tool_paint_due(id, output))?
        .to_owned();
    Some(
        canvas(
            |_, _, _| (),
            move |_, _, _, _| {
                if output {
                    crate::stream_timing::tool_output_painted(&id);
                } else {
                    crate::stream_timing::tool_card_painted(&id);
                }
            },
        )
        .absolute()
        .top(px(0.0))
        .left(px(0.0))
        .size(px(1.0)),
    )
}

fn chat_tool_content(
    pane_id: usize,
    index: usize,
    tool: &ChatTool,
    tokens: ThemeTokens,
    on_show_more: impl Fn(&MouseDownEvent, &mut Window, &mut App) + 'static,
) -> Div {
    let mut body = div()
        .w_full()
        .min_w_0()
        .when(tool.display.shell_command.is_none(), |body| {
            body.pl(px(12.0))
        })
        .py(px(8.0))
        .flex()
        .flex_col()
        .gap(px(8.0));
    if !tool.output.is_empty()
        && let Some(marker) = tool_paint_marker(tool.id.as_deref(), true)
    {
        body = body.relative().child(marker);
    }

    if let Some(command) = tool.display.shell_command.as_ref() {
        body = body.child(chat_console_output(
            pane_id,
            index,
            ToolOutputView {
                full: command.clone(),
                preview: tool
                    .display
                    .shell_preview
                    .clone()
                    .unwrap_or_else(|| command.clone()),
                truncated: tool.display.shell_truncated,
                show_full: tool.show_full,
            },
            ToolOutputView {
                full: tool.output.clone(),
                preview: tool.preview.clone(),
                truncated: tool.preview_truncated,
                show_full: tool.show_full,
            },
            tool.state == ToolState::Failed,
            tokens,
            on_show_more,
        ));
    } else {
        let section_header = |label: &'static str, suffix: &'static str, text: SharedString| {
            div()
                .flex()
                .items_center()
                .justify_between()
                .text_size(px(11.0))
                .text_color(tokens.text_muted)
                .child(label)
                .child(chat_copy_button(
                    format!("copy-tool-{suffix}-{pane_id}-{index}").into(),
                    text,
                    format!("Copy {}", label.to_ascii_lowercase()).into(),
                    tokens,
                ))
        };
        if tool.display.show_raw_input && !tool.display.input.is_empty() {
            let input = if tool.show_full {
                tool.display.input.clone()
            } else {
                tool.display.input_preview.clone()
            };
            body = body
                .child(section_header("Input", "input", tool.display.input.clone()))
                .child(chat_tool_output_block(
                    format!("tool-input-{pane_id}-{index}").into(),
                    input,
                    false,
                    tokens,
                ));
        }
        if let Some(content) = tool.display.content_body.as_ref() {
            let display = if tool.show_full {
                content.clone()
            } else {
                tool.display
                    .content_preview
                    .clone()
                    .unwrap_or_else(|| content.clone())
            };
            body = body
                .child(section_header(
                    if tool.display.view.title == "Write" {
                        "Content"
                    } else {
                        "Changes"
                    },
                    "content",
                    content.clone(),
                ))
                .child(chat_tool_output_block(
                    format!("tool-content-{pane_id}-{index}").into(),
                    display,
                    false,
                    tokens,
                ));
        }
        if !tool.output.trim().is_empty() {
            let display = if tool.show_full {
                tool.output.clone()
            } else {
                tool.preview.clone()
            };
            body = body.child(section_header("Output", "output", tool.output.clone()));
            body = body.child(chat_tool_output_block(
                format!("tool-output-{pane_id}-{index}").into(),
                display,
                tool.state == ToolState::Failed,
                tokens,
            ));
        }
        if (tool.display.show_raw_input && tool.display.input_truncated)
            || tool.display.content_truncated
            || tool.preview_truncated
        {
            let hidden = if tool.display.show_raw_input {
                tool.display
                    .input
                    .len()
                    .saturating_sub(tool.display.input_preview.len())
            } else {
                0
            } + tool.display.content_body.as_ref().map_or(0, |content| {
                content.len().saturating_sub(
                    tool.display
                        .content_preview
                        .as_ref()
                        .map_or(0, |preview| preview.len()),
                )
            }) + tool.output.len().saturating_sub(tool.preview.len());
            body = body.child(chat_output_expander(
                SharedString::from(format!("tool-body-more-{pane_id}-{index}")),
                hidden,
                tool.show_full,
                tokens,
                on_show_more,
            ));
        }
    }
    let notice = match tool.state {
        ToolState::Failed if tool.output.is_empty() => Some("Tool execution failed."),
        ToolState::Unknown if tool.output.is_empty() => Some("Execution ended without a result."),
        _ => None,
    };
    if let Some(notice) = notice {
        body = body.child(
            div()
                .text_size(px(12.0))
                .text_color(if tool.state == ToolState::Failed {
                    tokens.block_failure
                } else {
                    tokens.text_muted
                })
                .child(notice),
        );
    }
    body
}

enum FaviconAsset {}

impl gpui::Asset for FaviconAsset {
    type Source = String;
    type Output = Result<Arc<gpui::RenderImage>, gpui::ImageCacheError>;

    fn load(source: String, cx: &mut App) -> impl Future<Output = Self::Output> + Send + 'static {
        static SLOTS: std::sync::LazyLock<(
            smol::channel::Sender<()>,
            smol::channel::Receiver<()>,
        )> = std::sync::LazyLock::new(|| {
            let (sender, receiver) = smol::channel::bounded(4);
            for _ in 0..4 {
                let _ = sender.try_send(());
            }
            (sender, receiver)
        });
        let renderer = cx.svg_renderer();
        async move {
            let _ = SLOTS.1.recv().await;
            let result = smol::unblock(move || -> anyhow::Result<Arc<gpui::RenderImage>> {
                use std::io::Read as _;
                static CLIENT: std::sync::LazyLock<
                    Result<reqwest::blocking::Client, reqwest::Error>,
                > = std::sync::LazyLock::new(|| {
                    reqwest::blocking::Client::builder()
                        .timeout(std::time::Duration::from_secs(5))
                        .build()
                });
                let client = CLIENT
                    .as_ref()
                    .map_err(|error| anyhow::anyhow!("{error}"))?;
                let response = client
                    .get("https://www.google.com/s2/favicons")
                    .query(&[("domain", source.as_str()), ("sz", "32")])
                    .send()?
                    .error_for_status()?;
                let mut bytes = Vec::new();
                response.take(64 * 1024 + 1).read_to_end(&mut bytes)?;
                anyhow::ensure!(bytes.len() <= 64 * 1024, "favicon too large");
                gpui::Image::from_bytes(gpui::ImageFormat::Png, bytes).to_image_data(renderer)
            })
            .await;
            let _ = SLOTS.0.try_send(());
            result.map_err(Into::into)
        }
    }
}

fn web_sources(name: &str, output: &str) -> Vec<String> {
    if !matches!(
        name.to_ascii_lowercase().as_str(),
        "websearch" | "web_search" | "search_web" | "webfetch" | "web_fetch" | "fetch"
    ) {
        return Vec::new();
    }
    let mut sources = Vec::new();
    // Keep work and retained data bounded even when a tool returns a large page.
    let end = output.floor_char_boundary(output.len().min(128 * 1024));
    for part in output[..end].split(|c: char| {
        c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>' | '(' | ')' | '[' | ']' | ',')
    }) {
        let Some(start) = part.find("https://").or_else(|| part.find("http://")) else {
            continue;
        };
        let candidate = part[start..].trim_end_matches(['.', ';']);
        if let Ok(url) = url::Url::parse(candidate)
            && let Some(host) = url.host_str()
        {
            let host = host.trim_start_matches("www.");
            if !sources.iter().any(|source| source == host) {
                sources.push(host.to_owned());
                if sources.len() == 100 {
                    break;
                }
            }
        }
    }
    sources
}

fn chat_tool_header(
    pane_id: usize,
    index: usize,
    tool: &ChatTool,
    tokens: ThemeTokens,
    on_toggle: impl Fn(&MouseDownEvent, &mut Window, &mut App) + 'static,
) -> impl IntoElement {
    use gpui_component::IconName;

    let view = &tool.display.view;
    let running = tool.state == ToolState::Running;
    let failed = tool.state == ToolState::Failed;
    let icon = match view.title.as_str() {
        "Batch" => IconName::GalleryVerticalEnd,
        "Shell" => IconName::SquareTerminal,
        "Read" => IconName::BookOpen,
        "List" => IconName::FolderClosed,
        "Web Search" | "Webfetch" | "Browser" => IconName::Globe,
        "Grep" | "Glob" => IconName::Search,
        "Edit" | "Patch" => IconName::Replace,
        _ if is_agent_tool(&tool.name) => IconName::Bot,
        _ => IconName::File,
    };

    let color = if failed {
        tokens.block_failure
    } else {
        tokens.text_primary
    };
    let icon_color = if failed { color } else { tokens.text_muted };

    let row = div()
        .id(SharedString::from(format!("tool-row-{pane_id}-{index}")))
        .debug_selector(move || format!("tool-row-{index}"))
        .w_full()
        .min_w_0()
        .h(px(28.0))
        .flex()
        .items_center()
        .gap(px(8.0))
        .text_size(px(13.0))
        .text_color(color)
        .cursor(CursorStyle::PointingHand)
        .hover(move |style| style.text_color(if failed { color } else { tokens.text_primary }))
        .on_mouse_down(MouseButton::Left, on_toggle)
        .child(
            div().flex_shrink_0().child(
                gpui_component::Icon::new(if failed {
                    IconName::TriangleAlert
                } else {
                    icon
                })
                .size(px(14.0))
                .text_color(icon_color),
            ),
        )
        .child(
            div()
                .flex_shrink_0()
                .font_weight(gpui::FontWeight::MEDIUM)
                .child(if failed {
                    format!("{} failed", view.title)
                } else {
                    view.title.clone()
                }),
        )
        .when(chat_batch::is_batch(&tool.name), |row| {
            row.child(
                div()
                    .min_w_0()
                    .truncate()
                    .text_color(tokens.text_muted)
                    .child(chat_batch::counts(tool)),
            )
        })
        .when_some(
            tool.batch_result
                .as_ref()
                .filter(|result| result.failed_count() > 0),
            |row, result| {
                row.child(
                    div()
                        .flex_shrink_0()
                        .text_color(tokens.block_failure)
                        .child(format!("{} failed", result.failed_count())),
                )
            },
        )
        .when(running, |row| {
            row.child(
                div()
                    .min_w_0()
                    .truncate()
                    .text_color(tokens.text_muted)
                    .child("· Running…"),
            )
        })
        .when(
            !view.subtitle.is_empty() && !(view.title == "Shell" && tool.expanded),
            |row| {
                row.child(
                    div()
                        .min_w_0()
                        .truncate()
                        .text_color(tokens.text_muted)
                        .child(view.subtitle.clone()),
                )
            },
        )
        .children(view.args.iter().map(|arg| {
            div()
                .min_w_0()
                .truncate()
                .text_color(tokens.text_muted)
                .child(arg.clone())
        }))
        .when(!tool.web_sources.is_empty(), |row| {
            let mut avatars = div().flex().items_center().flex_shrink_0();
            for (index, source) in tool.web_sources.iter().take(3).enumerate() {
                let initial = source
                    .chars()
                    .next()
                    .unwrap_or('?')
                    .to_ascii_uppercase()
                    .to_string();
                let host = source.clone();
                let fallback_initial = initial.clone();
                let fallback = move || {
                    div()
                        .size_full()
                        .flex()
                        .items_center()
                        .justify_center()
                        .text_size(px(10.0))
                        .text_color(tokens.text_primary)
                        .child(fallback_initial.clone())
                        .into_any_element()
                };
                let loading = fallback.clone();
                avatars = avatars.child(
                    div()
                        .when(index > 0, |avatar| avatar.ml(px(-4.0)))
                        .size(px(16.0))
                        .rounded_full()
                        .border_1()
                        .border_color(tokens.border_subtle)
                        .bg(tokens.sidebar_item_hover)
                        .flex()
                        .items_center()
                        .justify_center()
                        .text_size(px(10.0))
                        .text_color(tokens.text_primary)
                        .overflow_hidden()
                        .child(
                            img(move |window: &mut Window, cx: &mut App| {
                                window.use_asset::<FaviconAsset>(&host, cx)
                            })
                            .size_full()
                            .with_loading(loading)
                            .with_fallback(fallback),
                        ),
                );
            }
            row.child(avatars)
                .child(
                    div()
                        .flex_shrink_0()
                        .text_color(tokens.text_muted)
                        .child(format!(
                            "{} {}",
                            tool.web_sources.len(),
                            if tool.web_sources.len() == 1 {
                                "site"
                            } else {
                                "sites"
                            }
                        )),
                )
        })
        .child(
            svg()
                .path(if tool.expanded {
                    "icons/chevron-down.svg"
                } else {
                    "icons/chevron-right.svg"
                })
                .size(px(12.0))
                .flex_shrink_0()
                .text_color(tokens.text_muted),
        );

    row.into_any_element()
}

fn chat_tool_card(
    pane_id: usize,
    index: usize,
    tool: &ChatTool,
    tokens: ThemeTokens,
    host: &UiHost,
    on_toggle: impl Fn(&MouseDownEvent, &mut Window, &mut App) + 'static,
    on_show_more: impl Fn(&MouseDownEvent, &mut Window, &mut App) + 'static,
) -> Div {
    if chat_batch::is_batch(&tool.name) && chat_batch::known_count(tool).is_some() {
        let mut calls = div()
            .w_full()
            .min_w_0()
            .flex()
            .flex_col()
            .child(chat_tool_header(pane_id, index, tool, tokens, on_toggle));
        if tool.expanded {
            calls = calls.child(chat_batch::details(
                div()
                    .w_full()
                    .min_w_0()
                    .flex()
                    .flex_col()
                    .gap(px(2.0))
                    .pl(px(12.0)),
                pane_id,
                index,
                tool,
                tokens,
                host,
            ));
        }
        if let Some(marker) = tool_paint_marker(tool.id.as_deref(), false) {
            calls = calls.relative().child(marker);
        }
        if !tool.output.is_empty()
            && let Some(marker) = tool_paint_marker(tool.id.as_deref(), true)
        {
            calls = calls.relative().child(marker);
        }
        return calls;
    }
    let mut card = div()
        .w_full()
        .min_w_0()
        .flex()
        .flex_col()
        .child(chat_tool_header(pane_id, index, tool, tokens, on_toggle));

    if let Some(marker) = tool_paint_marker(tool.id.as_deref(), false) {
        card = card.relative().child(marker);
    }

    if tool.expanded {
        card = card.child(chat_tool_content(
            pane_id,
            index,
            tool,
            tokens,
            on_show_more,
        ));
    }
    card
}

fn chat_thinking_row(
    pane_id: usize,
    index: usize,
    message: &ChatMessage,
    running: bool,
    render: ChatRenderContext<'_>,
    on_toggle: impl Fn(&MouseDownEvent, &mut Window, &mut App) + 'static,
) -> Div {
    let ChatRenderContext { tokens, window, cx } = render;
    let expanded = message.expanded;
    let running = running && message.streaming;
    let heading_end = message
        .text
        .char_indices()
        .nth(81)
        .map_or(message.text.len(), |(index, _)| index);
    let heading = clip_tool_text(first_line(&message.text[..heading_end]), 80).0;
    let label = if running { "Thinking" } else { "Thought" };

    let title = div()
        .flex_shrink_0()
        .text_size(px(13.0))
        .font_weight(gpui::FontWeight::MEDIUM)
        .text_color(tokens.text_primary)
        .child(label);
    // The label already reads "Thinking" while streaming and "Thought" after.
    // A repeating pulse here would repaint the window for the whole reasoning
    // phase (AGENTS.md: no continuously repainting animations).
    let title = title.into_any_element();

    let mut header = div()
        .id(SharedString::from(format!(
            "thinking-row-{pane_id}-{index}"
        )))
        .w_full()
        .min_w_0()
        .h(px(28.0))
        .flex()
        .items_center()
        .gap(px(6.0))
        .cursor(CursorStyle::PointingHand)
        .on_mouse_down(MouseButton::Left, on_toggle)
        .child(title);

    if !expanded && !heading.is_empty() {
        header = header.child(
            div()
                .min_w_0()
                .truncate()
                .text_size(px(13.0))
                .text_color(tokens.text_muted)
                .child(heading),
        );
    }

    header = header.child(div().flex_1()).child(
        svg()
            .path(if expanded {
                "icons/chevron-down.svg"
            } else {
                "icons/chevron-right.svg"
            })
            .size(px(12.0))
            .flex_shrink_0()
            .text_color(tokens.text_muted),
    );

    let mut row = div()
        .w_full()
        .min_w_0()
        .flex()
        .flex_col()
        .debug_selector(move || format!("thinking-row-{index}"))
        .child(header);

    if expanded {
        let body_id = SharedString::from(format!("thinking-body-{pane_id}-{index}"));
        let mut body = div().w_full().min_w_0().flex().flex_col().gap(px(6.0));
        if let Some(view) = message.stream.as_ref() {
            if !view.settled.is_empty() {
                body = body.child(chat_markdown(
                    body_id,
                    view.settled.clone(),
                    px(12.5),
                    rems(0.4),
                    tokens.text_muted,
                    ChatRenderContext { tokens, window, cx },
                ));
            }
            if !view.tail.is_empty() {
                body = body.child(chat_stream_tail(
                    SharedString::from(format!("thinking-body-{pane_id}-{index}-live")),
                    view,
                    px(12.5),
                    rems(0.4),
                    tokens.text_muted,
                    ChatRenderContext { tokens, window, cx },
                ));
            }
        } else {
            body = body.child(chat_markdown(
                body_id,
                message.markdown(),
                px(12.5),
                rems(0.4),
                tokens.text_muted,
                ChatRenderContext { tokens, window, cx },
            ));
        }
        row = row.child(
            div()
                .w_full()
                .min_w_0()
                .ml(px(12.0))
                .pl(px(12.0))
                .border_l_1()
                .border_color(tokens.border_subtle)
                .py(px(6.0))
                .debug_selector(move || format!("thinking-body-{index}"))
                .child(body),
        );
    }
    row
}

fn update_chat_tool(
    messages: &mut Vec<Arc<ChatMessage>>,
    id: Option<String>,
    name: String,
    output: String,
    state: ToolState,
) {
    // An absent ID cannot distinguish concurrent calls with the same name.
    // Associate those events with the oldest matching running call.
    let existing = messages
        .iter()
        .rev()
        .take_while(|message| message.role != ChatRole::User)
        .enumerate()
        .filter_map(|(offset, message)| {
            message
                .tool
                .as_ref()
                .filter(|tool| tool.state == ToolState::Running)
                .filter(|tool| match id.as_ref() {
                    Some(id) => tool.id.as_ref() == Some(id),
                    None => tool.id.is_none() && tool.name == name,
                })
                .map(|_| offset)
        })
        .last()
        .map(|offset| messages.len() - 1 - offset);
    let workers = if state == ToolState::Completed {
        subagent_chat::legacy(&name, &output)
    } else {
        Vec::new()
    };
    let batch_result = (state == ToolState::Completed && chat_batch::is_batch(&name))
        .then(|| chat_batch::BatchResult::parse(&output).map(Arc::new))
        .flatten();
    let failure_preview = (state == ToolState::Failed && chat_batch::is_batch(&name))
        .then(|| chat_batch::failure_preview(&output))
        .flatten();
    let (full, preview, truncated) = if let Some(preview) = failure_preview {
        (
            SharedString::from(output),
            SharedString::from(preview),
            true,
        )
    } else {
        tool_output_fields(output)
    };
    if let Some(index) = existing {
        let message = Arc::make_mut(&mut messages[index]);
        let tool = message.tool.as_mut().expect("matched a tool message");
        subagent_chat::update_workers(&mut tool.workers, workers);
        if state == ToolState::Completed {
            match tool.display.view.title.as_str() {
                "Webfetch" => tool.web_sources = web_sources(&name, &tool.display.view.subtitle),
                "Web Search" => tool.web_sources = web_sources(&name, &full),
                _ => {}
            }
        }
        tool.output = full;
        tool.preview = preview;
        tool.preview_truncated = truncated;
        tool.batch_result = batch_result;
        tool.state = state;
        if chat_batch::is_batch(&tool.name) && state != ToolState::Running {
            tool.expanded = false;
        }
    } else {
        let display = ToolDisplay::new(&name, "");
        messages.push(Arc::new(ChatMessage {
            role: ChatRole::Tool,
            text: String::new(),
            tool: Some(ChatTool {
                workers,
                web_sources: if state == ToolState::Completed {
                    web_sources(&name, &full)
                } else {
                    Vec::new()
                },
                id,
                name,
                output: full,
                preview,
                preview_truncated: truncated,
                batch_result,
                state,
                expanded: false,
                expanded_calls: [false; embedded::MAX_BATCH_CALLS],
                display,
                show_full: false,
            }),
            expanded: false,
            streaming: false,
            stream: None,
            markdown: std::sync::OnceLock::new(),
            literal: std::sync::OnceLock::new(),
            turn: None,
            source_timestamp: None,
        }));
    }
}

fn provider_icon_stems() -> &'static std::collections::HashSet<String> {
    static STEMS: std::sync::LazyLock<std::collections::HashSet<String>> =
        std::sync::LazyLock::new(|| {
            let mut stems = std::collections::HashSet::new();
            for asset in assets::AppAssets::iter() {
                if let Some(name) = asset
                    .strip_prefix("icons/provider/")
                    .and_then(|name| name.strip_suffix(".svg"))
                {
                    stems.insert(name.to_string());
                }
            }
            if let Ok(entries) = std::fs::read_dir("assets/icons/provider") {
                for entry in entries.flatten() {
                    let path = entry.path();
                    if path.extension().is_some_and(|ext| ext == "svg")
                        && let Some(stem) = path.file_stem().and_then(|stem| stem.to_str())
                    {
                        stems.insert(stem.to_string());
                    }
                }
            }
            stems
        });
    &STEMS
}

fn provider_icon_stem(id: &str) -> &str {
    match id {
        "opencode" | "opencode-zen" => "opencode",
        "google-antigravity" | "google-gemini-cli" => "google",
        "xai-oauth" => "xai",
        "lm-studio" => "lmstudio",
        "ollama" => "ollama-cloud",
        "fireworks" => "fireworks-ai",
        "novita" => "novita-ai",
        "together" => "togetherai",
        "cloudflare" => "cloudflare-workers-ai",
        "azure-openai" => "azure",
        "bedrock" | "aws-bedrock" => "amazon-bedrock",
        "copilot" => "github-copilot",
        "kimi" | "kimi-code" => "kimi-for-coding",
        "zhipu" => "zhipuai",
        "moonshot" => "moonshotai",
        "openai-codex" | "openai-codex-device" => "openai",
        "gitlab-duo" | "gitlab-duo-agent" => "gitlab",
        other => other,
    }
}

/// Monochrome OpenCode provider mark. Unknown ids use the generic sparkle.
fn provider_icon_path(id: &str) -> SharedString {
    let stem = provider_icon_stem(id);
    let stem = if provider_icon_stems().contains(stem) {
        stem
    } else {
        "synthetic"
    };
    SharedString::from(format!("icons/provider/{stem}.svg"))
}

