fn provider_display_name(id: &str) -> String {
    let (name, _) = provider_metadata(id);
    if !name.is_empty() {
        name.to_string()
    } else {
        id.to_string()
    }
}

fn provider_featured_rank(id: &str) -> usize {
    match id {
        "openai" => 0,
        "anthropic" => 1,
        "google" => 2,
        "github-copilot" | "copilot" => 3,
        "google-antigravity" => 4,
        _ => usize::MAX,
    }
}

/// Fallback sidebar title when the first prompt's title request fails.
fn agent_title_from_prompt(prompt: &str) -> Option<String> {
    let line = prompt
        .lines()
        .map(str::trim)
        .find(|line| !line.is_empty() && !line.starts_with('/'))?;
    let collapsed = line.split_whitespace().collect::<Vec<_>>().join(" ");
    if collapsed.is_empty() {
        return None;
    }
    Some(match collapsed.char_indices().nth(64) {
        Some((index, _)) => format!("{}…", &collapsed[..index]),
        None => collapsed,
    })
}

/// The `provider/model` selector both agent backends are launched with.
///
/// Model ids may themselves contain slashes (`commandcode` +
/// `deepseek/deepseek-v4-flash`), so the provider is always prefixed instead of
/// letting the backend guess a provider from the id. Every launch path must use
/// this, otherwise a pane runs a different model than the chip shows.
fn agent_model_selector(model: &agent_auth::AgentModel) -> String {
    format!("{}/{}", model.provider, model.id)
}

/// Assistant text stops streaming whenever the agent moves on to thinking,
/// activity, a tool call, an error, or the end of the turn. The next text
/// event starts a fresh streaming message, so completed text gets the full
/// markdown render again. Completed thinking folds into its compact header.
fn finish_chat_streaming(messages: &mut [Arc<ChatMessage>]) {
    // Only the newest message can be streaming: every other role calls this
    // before pushing, so scanning the whole transcript here is wasted work.
    if let Some(message) = messages.last_mut()
        && message.streaming
    {
        let message = Arc::make_mut(message);
        message.streaming = false;
        if let Some(view) = message.stream.take() {
            view.settled
                .finish(SharedString::from(message.text.clone()));
            let _ = message.markdown.set(view.settled);
        }
        if message.role == ChatRole::Thinking {
            message.expanded = false;
        }
    }
}

/// Cap live scans, copies and parser input independently of unfinished block size.
/// Once oversized, keep a plain suffix until finalization; never fragment a
/// fence/list into separately parsed pieces with lost syntax or numbering.
fn refresh_stream_view(message: &mut ChatMessage, scan: bool) {
    if message.stream.is_none() {
        let _ = message.markdown.take();
    }
    let previous = message.stream.as_ref().map_or(0, |view| view.settled.len());
    let plain_tail = message.stream.as_ref().is_some_and(|view| view.plain_tail)
        || message.text.len() - previous > STREAM_LIVE_BYTES;
    let split_at = if scan && !plain_tail {
        let (_, tail) = split_streaming_markdown(&message.text[previous..]);
        message.text.len() - tail.len()
    } else {
        previous
    };
    let mut tail_at = split_at.max(message.text.len().saturating_sub(STREAM_LIVE_BYTES));
    while !message.text.is_char_boundary(tail_at) {
        tail_at += 1;
    }
    let tail = SharedString::from(&message.text[tail_at..]);
    if let Some(view) = message.stream.as_mut() {
        if previous != split_at {
            view.settled
                .push(SharedString::from(&message.text[previous..split_at]));
        }
        view.tail = tail;
        view.plain_tail = plain_tail;
    } else {
        let settled = MarkdownBlocks::default();
        if split_at > 0 {
            settled.push(SharedString::from(&message.text[..split_at]));
        }
        message.stream = Some(StreamView {
            settled,
            tail,
            plain_tail,
        });
    }
}

fn finish_chat_tools(messages: &mut [Arc<ChatMessage>]) {
    for message in messages
        .iter_mut()
        .rev()
        .take_while(|message| message.role != ChatRole::User)
    {
        if message
            .tool
            .as_ref()
            .is_some_and(|tool| tool.state == ToolState::Running)
            && let Some(tool) = Arc::make_mut(message).tool.as_mut()
        {
            tool.state = ToolState::Unknown;
            if chat_batch::is_batch(&tool.name) {
                tool.expanded = false;
            }
        }
    }
}

const TASK_LIST_COMPLETION_DELAY: std::time::Duration = std::time::Duration::from_secs(2);

fn is_task_list_event(event: &agent_bridge::AgentEvent) -> bool {
    use agent_bridge::AgentEvent;
    matches!(
        event,
        AgentEvent::ToolStart { name, .. }
            | AgentEvent::ToolUpdate { name, .. }
            | AgentEvent::ToolEnd { name, .. }
            if name == embedded::task_list::NAME
    )
}

fn task_list_update(event: &agent_bridge::AgentEvent) -> Option<embedded::task_list::TaskList> {
    match event {
        agent_bridge::AgentEvent::ToolEnd {
            name,
            output,
            failed: false,
            ..
        } if name == embedded::task_list::NAME => serde_json::from_str(output).ok(),
        _ => None,
    }
}

fn active_task_index(list: &embedded::task_list::TaskList) -> Option<usize> {
    list.tasks
        .iter()
        .position(|task| task.status == embedded::task_list::TaskStatus::InProgress)
}

fn task_list_completed(list: &embedded::task_list::TaskList) -> bool {
    !list.tasks.is_empty()
        && list
            .tasks
            .iter()
            .all(|task| task.status == embedded::task_list::TaskStatus::Completed)
}

fn push_chat_event(messages: &mut Vec<Arc<ChatMessage>>, event: agent_bridge::AgentEvent) {
    if is_task_list_event(&event) {
        return;
    }
    let (role, text) = match event {
        agent_bridge::AgentEvent::ToolStart { id, name, input } => {
            if let Some(id) = id.as_deref() {
                crate::stream_timing::tool_applied(id);
            }
            // Finalize the streaming block before the tool card becomes the
            // newest message; finalization only looks at the tail.
            finish_chat_streaming(messages);
            if let Some(id) = id.as_deref()
                && let Some(tool) = messages.iter_mut().rev().find_map(|message| {
                    let tool = message.tool.as_ref()?;
                    if tool.id.as_deref() != Some(id) || tool.workers.is_empty() {
                        return None;
                    }
                    Arc::make_mut(message).tool.as_mut()
                })
            {
                tool.display = ToolDisplay::new(&name, &input);
                tool.name = name;
                return;
            }
            let display = ToolDisplay::new(&name, &input);
            let expanded = chat_batch::is_batch(&name);
            messages.push(Arc::new(ChatMessage {
                role: ChatRole::Tool,
                text: String::new(),
                tool: Some(ChatTool {
                    workers: Vec::new(),
                    web_sources: Vec::new(),
                    id,
                    name,
                    output: SharedString::from(""),
                    preview: SharedString::from(""),
                    preview_truncated: false,
                    batch_result: None,
                    state: ToolState::Running,
                    expanded,
                    expanded_calls: [false; embedded::MAX_BATCH_CALLS],
                    display,
                    show_full: false,
                }),
                expanded: false,
                streaming: false,
                stream: None,
                markdown: std::sync::OnceLock::new(),
                literal: std::sync::OnceLock::new(),
                turn: None,
                source_timestamp: None,
            }));
            return;
        }
        agent_bridge::AgentEvent::ToolUpdate { id, name, output } => {
            finish_chat_streaming(messages);
            update_chat_tool(messages, id, name, output, ToolState::Running);
            return;
        }
        agent_bridge::AgentEvent::ToolEnd {
            id,
            name,
            output,
            failed,
        } => {
            finish_chat_streaming(messages);
            update_chat_tool(
                messages,
                id,
                name,
                output,
                if failed {
                    ToolState::Failed
                } else {
                    ToolState::Completed
                },
            );
            return;
        }
        agent_bridge::AgentEvent::Subagents { tool_id, workers } => {
            if let Some(message) = messages.iter_mut().rev().find(|message| {
                message
                    .tool
                    .as_ref()
                    .is_some_and(|tool| tool.id.as_deref() == Some(tool_id.as_str()))
            }) {
                if let Some(tool) = Arc::make_mut(message).tool.as_mut() {
                    subagent_chat::update_workers(&mut tool.workers, workers);
                }
            } else {
                push_chat_event(
                    messages,
                    agent_bridge::AgentEvent::ToolStart {
                        id: Some(tool_id),
                        name: "task".into(),
                        input: String::new(),
                    },
                );
                if let Some(tool) = messages
                    .last_mut()
                    .and_then(|message| Arc::make_mut(message).tool.as_mut())
                {
                    subagent_chat::update_workers(&mut tool.workers, workers);
                }
            }
            return;
        }
        agent_bridge::AgentEvent::Text(text) => (ChatRole::Assistant, text),
        agent_bridge::AgentEvent::Thinking(text) => (ChatRole::Thinking, text),
        agent_bridge::AgentEvent::Status(text) => (ChatRole::Status, text),
        agent_bridge::AgentEvent::Tool(text) => (ChatRole::Tool, text),
        agent_bridge::AgentEvent::Error(text) => (ChatRole::Error, text),
        // The session title is metadata, not transcript content.
        agent_bridge::AgentEvent::Title(_)
        | agent_bridge::AgentEvent::Usage(_)
        | agent_bridge::AgentEvent::Done
        | agent_bridge::AgentEvent::Closed => return,
    };
    if messages.last().is_some_and(|last| last.role != role) {
        finish_chat_streaming(messages);
    }
    if matches!(role, ChatRole::Assistant | ChatRole::Thinking)
        && let Some(last) = messages.last_mut().filter(|message| message.role == role)
    {
        let last = Arc::make_mut(last);
        last.text.push_str(&text);
        // Reasoning streams like assistant text: settled blocks stay cached and
        // only the live tail is re-parsed, instead of reparsing the whole block
        // on every throttled tick.
        last.streaming = true;
        refresh_stream_view(last, text.contains('\n'));
        return;
    }
    let mut message = ChatMessage::new(role, text);
    if matches!(role, ChatRole::Assistant | ChatRole::Thinking) {
        message.streaming = true;
        refresh_stream_view(&mut message, true);
    }
    messages.push(Arc::new(message));
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum AgentDialogPage {
    Auth,
    Models,
}

#[derive(Clone, PartialEq, Eq)]
enum ModelPickerFilter {
    All,
    Favorites,
    Provider(String),
}

struct AuthModal {
    page: AgentDialogPage,
    model_filter: ModelPickerFilter,
    model_scroll: VirtualListScrollHandle,
    provider_scroll: VirtualListScrollHandle,
    focus: gpui::FocusHandle,
    cwd: PathBuf,
    providers: Vec<agent_auth::Provider>,
    discovery: Option<std::sync::mpsc::Receiver<Result<Vec<agent_auth::Provider>, String>>>,
    models: Vec<agent_auth::AgentModel>,
    model_discovery: Option<std::sync::mpsc::Receiver<Result<Vec<agent_auth::AgentModel>, String>>>,
    model_error: Option<String>,
    custom_provider: Option<[Entity<InputState>; 5]>,
    provider_operation: Option<std::sync::mpsc::Receiver<Result<Option<String>, String>>>,
    provider_input: Entity<InputState>,
    filter: Entity<InputState>,
    input: Entity<InputState>,
    login: Option<agent_auth::Login>,
    selected: Option<String>,
    output: String,
    error: Option<String>,
}

impl AuthModal {
    fn provider_name(&self, id: &str) -> String {
        self.providers
            .iter()
            .find(|p| p.id == id)
            .and_then(|p| p.name.clone())
            .unwrap_or_else(|| provider_display_name(id))
    }

    fn filter_models(&mut self, filter: ModelPickerFilter) {
        self.model_filter = if self.model_filter == filter {
            ModelPickerFilter::All
        } else {
            filter
        };
        self.model_scroll.set_offset(gpui::point(px(0.0), px(0.0)));
    }

    fn discover(&mut self) {
        self.error = None;
        self.model_error = None;
        let (sender, receiver) = std::sync::mpsc::channel();
        let cwd = self.cwd.clone();
        std::thread::spawn(move || {
            let _ = sender.send(agent_auth::providers(&cwd));
        });
        self.discovery = Some(receiver);
        let (sender, receiver) = std::sync::mpsc::channel();
        let cwd = self.cwd.clone();
        std::thread::spawn(move || {
            let _ = sender.send(agent_auth::available_models(&cwd));
        });
        self.model_discovery = Some(receiver);
    }
}

type ModelBridge = agent_bridge::AgentBridge;

struct WorkerView {
    index: usize,
    id: String,
    scroll: gpui::ScrollHandle,
    messages: Vec<Arc<ChatMessage>>,
    expanded: HashSet<usize>,
    full_output: HashSet<usize>,
    _load: Option<gpui::Task<()>>,
}

/// Owned worker display data, refreshed only when worker activity changes.
#[derive(Clone)]
struct WorkerRowSnapshot {
    index: usize,
    id: String,
    avatar: usize,
    title: String,
    status: &'static str,
}

/// One virtualized transcript unit. Settled history stays measured and is not
/// rebuilt when the active reply grows.
enum ChatRow {
    Subagents {
        start: usize,
        rows: Vec<WorkerRowSnapshot>,
    },
    ToolGroup {
        start: usize,
        messages: Vec<Arc<ChatMessage>>,
        live: bool,
        open: bool,
    },
    Message {
        index: usize,
        message: Arc<ChatMessage>,
        live: bool,
        copy_range: Option<(usize, usize)>,
    },
    Running {
        label: SharedString,
        tooltip: SharedString,
    },
}

#[derive(Clone, Copy, Default)]
struct ChatRowCheckpoint {
    cursor: usize,
    turn_start: usize,
    last_assistant_row: Option<usize>,
    active_row: Option<usize>,
}

#[derive(Default)]
struct ChatRowCache {
    conversation: Option<String>,
    rows: Vec<ChatRow>,
    checkpoints: Vec<ChatRowCheckpoint>,
    state: ChatRowCheckpoint,
    message_count: usize,
    running: bool,
    tail: usize,
    dirty: bool,
    workers_dirty: bool,
    workers: Vec<WorkerRowSnapshot>,
    activity: Option<(SharedString, SharedString)>,
    #[cfg(test)]
    built_rows: usize,
}

impl ChatRowCache {
    fn invalidate_from(&mut self, index: usize) {
        if self.dirty && index >= self.state.cursor {
            return;
        }
        let row = self
            .checkpoints
            .partition_point(|checkpoint| checkpoint.cursor <= index)
            .saturating_sub(1);
        if let Some(checkpoint) = self.checkpoints.get(row).copied() {
            self.state = checkpoint;
            self.rows.truncate(row);
            self.checkpoints.truncate(row);
        }
        self.dirty = true;
    }

    fn invalidate_workers(&mut self) {
        self.workers_dirty = true;
        let first = self
            .workers
            .first()
            .map_or(self.state.cursor, |worker| worker.index);
        self.invalidate_from(first);
    }
}

/// Row storage is shared with list callbacks; invalidation drops mutable
/// message handles before the next event, avoiding copy-on-write of live text.
struct ChatSnapshot {
    focused_layout: bool,
    pane_id: usize,
    conversation: SharedString,
    tokens: ThemeTokens,
    rows: std::rc::Rc<std::cell::RefCell<ChatRowCache>>,
    host: UiHost,
}

#[cfg(test)]
mod chat_row_cache_tests {
    use super::*;
    use agent_bridge::AgentEvent;

    fn apply(chat: &mut PaneChat, event: AgentEvent) {
        chat.observe_status(&event);
        match event {
            AgentEvent::Done | AgentEvent::Closed => {
                finish_chat_tools(&mut chat.messages);
                finish_chat_streaming(&mut chat.messages);
            }
            event => push_chat_event(&mut chat.messages, event),
        }
    }

    fn build(chat: &PaneChat) -> Rc<std::cell::RefCell<ChatRowCache>> {
        AppState::build_chat_rows(chat, chat.running)
    }

    #[test]
    fn unchanged_frames_and_bursty_deltas_reuse_history_without_cloning_live_text() {
        let mut chat = PaneChat::default();
        for _ in 0..200 {
            chat.messages
                .push(Arc::new(ChatMessage::new(ChatRole::User, "prompt".into())));
            chat.messages.push(Arc::new(ChatMessage::new(
                ChatRole::Assistant,
                "answer".into(),
            )));
        }
        chat.messages
            .push(Arc::new(ChatMessage::new(ChatRole::User, "next".into())));
        chat.running = true;
        apply(&mut chat, AgentEvent::Text("streaming ".repeat(100)));
        let snapshot = build(&chat);
        let built = snapshot.borrow().built_rows;
        let activity = snapshot.borrow().activity.clone().unwrap();
        build(&chat);
        assert_eq!(snapshot.borrow().built_rows, built);
        let last = chat.messages.len() - 1;
        let address = Arc::as_ptr(&chat.messages[last]);
        for _ in 0..8 {
            let event = AgentEvent::Text("more ".into());
            chat.observe_status(&event);
            assert_eq!(Arc::strong_count(&chat.messages[last]), 1);
            push_chat_event(&mut chat.messages, event);
            assert_eq!(Arc::as_ptr(&chat.messages[last]), address);
        }
        build(&chat);
        let cache = snapshot.borrow();
        assert_eq!(cache.built_rows - built, 2);
        assert_eq!(cache.activity.as_ref(), Some(&activity));
        assert!(matches!(&cache.rows[cache.rows.len() - 2],
            ChatRow::Message { message, .. } if message.text.ends_with("more more more more more more more more ")));
    }

    #[test]
    fn parallel_tools_folding_and_running_transitions_refresh_cached_rows() {
        let mut chat = PaneChat {
            running: true,
            ..Default::default()
        };
        chat.messages
            .push(Arc::new(ChatMessage::new(ChatRole::User, "prompt".into())));
        apply(&mut chat, AgentEvent::Text("first".into()));
        for id in ["one", "two"] {
            apply(
                &mut chat,
                AgentEvent::ToolStart {
                    id: Some(id.into()),
                    name: "read".into(),
                    input: "{}".into(),
                },
            );
        }
        apply(&mut chat, AgentEvent::Text("answer".into()));
        let snapshot = build(&chat);
        apply(
            &mut chat,
            AgentEvent::ToolEnd {
                id: Some("one".into()),
                name: "read".into(),
                output: "contents".into(),
                failed: false,
            },
        );
        build(&chat);
        assert!(matches!(&snapshot.borrow().rows[2],
            ChatRow::ToolGroup { messages, live: true, open: true, .. }
                if messages[0].tool.as_ref().unwrap().output.as_ref() == "contents"
                    && messages[1].tool.as_ref().unwrap().state == ToolState::Running));
        apply(&mut chat, AgentEvent::Done);
        build(&chat);
        {
            let cache = snapshot.borrow();
            assert!(matches!(
                &cache.rows[2],
                ChatRow::ToolGroup {
                    live: false,
                    open: false,
                    ..
                }
            ));
            assert!(matches!(
                &cache.rows[3],
                ChatRow::Message {
                    live: false,
                    copy_range: Some((1, 4)),
                    ..
                }
            ));
            assert!(matches!(
                &cache.rows[1],
                ChatRow::Message {
                    copy_range: None,
                    ..
                }
            ));
            assert!(
                !cache
                    .rows
                    .iter()
                    .any(|row| matches!(row, ChatRow::Running { .. }))
            );
        }
        chat.expanded_tool_groups
            .entry(chat.conversation_key.clone())
            .or_default()
            .insert(2);
        chat.invalidate_message_row(2);
        build(&chat);
        assert!(matches!(
            &snapshot.borrow().rows[2],
            ChatRow::ToolGroup { open: true, .. }
        ));
        let messages = chat.visible_messages_mut();
        Arc::make_mut(&mut messages[2])
            .tool
            .as_mut()
            .unwrap()
            .expanded = true;
        chat.invalidate_message_row(2);
        build(&chat);
        assert!(
            matches!(&snapshot.borrow().rows[2], ChatRow::ToolGroup { messages, .. }
            if messages[0].tool.as_ref().unwrap().expanded)
        );
        chat.running = true;
        build(&chat);
        assert!(matches!(
            &snapshot.borrow().rows[3],
            ChatRow::Message {
                copy_range: None,
                ..
            }
        ));
        chat.running = false;
        build(&chat);
        assert!(matches!(
            &snapshot.borrow().rows[3],
            ChatRow::Message {
                copy_range: Some((1, 4)),
                ..
            }
        ));
    }

    #[test]
    fn cross_turn_worker_updates_refresh_the_original_deduplicated_row() {
        let mut chat = PaneChat::default();
        let mut worker = subagent_chat::Worker {
            id: "worker".into(),
            title: "FirstTitle".into(),
            status: "running".into(),
            transcript: Some(PathBuf::from("/sessions/worker.jsonl")),
            result: None,
        };
        chat.messages
            .push(Arc::new(ChatMessage::new(ChatRole::User, "first".into())));
        apply(
            &mut chat,
            AgentEvent::Subagents {
                tool_id: "first".into(),
                workers: vec![worker.clone()],
            },
        );
        apply(&mut chat, AgentEvent::Text("response".into()));
        let snapshot = build(&chat);
        chat.messages
            .push(Arc::new(ChatMessage::new(ChatRole::User, "second".into())));
        worker.status = "completed".into();
        worker.title = "UpdatedTitle".into();
        apply(
            &mut chat,
            AgentEvent::Subagents {
                tool_id: "second".into(),
                workers: vec![worker.clone()],
            },
        );
        build(&chat);
        {
            let cache = snapshot.borrow();
            assert!(matches!(&cache.rows[1], ChatRow::Subagents { rows, .. }
                if rows.len() == 1 && rows[0].title == "Updated Title" && rows[0].status == "finished"));
            assert_eq!(
                cache
                    .rows
                    .iter()
                    .filter(|row| matches!(row, ChatRow::Subagents { .. }))
                    .count(),
                1
            );
        }
        worker.status = "failed".into();
        apply(
            &mut chat,
            AgentEvent::Subagents {
                tool_id: "first".into(),
                workers: vec![worker],
            },
        );
        build(&chat);
        // The later completed report still wins, exactly as subagent_chat::rows specifies.
        assert!(
            matches!(&snapshot.borrow().rows[1], ChatRow::Subagents { rows, .. }
            if rows[0].status == "finished")
        );
    }

    #[test]
    fn restores_switches_and_panes_never_reuse_stale_content_or_folding() {
        let mut chat = PaneChat::default();
        apply(&mut chat, AgentEvent::Text("old".into()));
        let snapshot = build(&chat);
        *chat.visible_messages_mut() = vec![Arc::new(ChatMessage::new(
            ChatRole::Assistant,
            "restored".into(),
        ))];
        build(&chat);
        assert!(
            matches!(&snapshot.borrow().rows[0], ChatRow::Message { message, .. }
            if message.text == "restored")
        );
        let original = chat.conversation_key.clone();
        chat.expanded_tool_groups
            .entry(original.clone())
            .or_default()
            .insert(0);
        chat.conversation_key = "another".into();
        *chat.visible_messages_mut() = Vec::new();
        apply(
            &mut chat,
            AgentEvent::ToolEnd {
                id: Some("tool".into()),
                name: "read".into(),
                output: "new".into(),
                failed: false,
            },
        );
        build(&chat);
        assert!(matches!(
            &snapshot.borrow().rows[0],
            ChatRow::ToolGroup { open: false, .. }
        ));
        chat.conversation_key = original;
        build(&chat);
        assert!(matches!(
            &snapshot.borrow().rows[0],
            ChatRow::ToolGroup { open: true, .. }
        ));
        let other = PaneChat::default();
        let other_rows = build(&other);
        assert!(!Rc::ptr_eq(&snapshot, &other_rows));
        assert!(other_rows.borrow().rows.is_empty());
        chat.visible_messages_mut().clear();
        build(&chat);
        assert!(snapshot.borrow().rows.is_empty());
    }
}

fn worker_status_label(label: &str) -> &'static str {
    match label {
        "Starting" => "is starting",
        "Running" => "is working",
        "Completed" => "finished",
        "Failed" => "failed",
        "Cancelled" => "was cancelled",
        "Idle" => "is idle",
        _ => "reported",
    }
}

fn chat_row_contains(row: &ChatRow, message_index: usize) -> bool {
    match row {
        ChatRow::Subagents { start, .. } => *start == message_index,
        ChatRow::ToolGroup {
            start, messages, ..
        } => (*start..*start + messages.len()).contains(&message_index),
        ChatRow::Message { index, .. } => *index == message_index,
        ChatRow::Running { .. } => false,
    }
}

/// Describe only activity supported by events from the current turn.
fn chat_activity(messages: &[Arc<ChatMessage>]) -> String {
    let mut turn = messages
        .iter()
        .rev()
        .take_while(|message| message.role != ChatRole::User);
    let mut active = turn.clone().filter_map(|message| {
        message
            .tool
            .as_ref()
            .filter(|tool| tool.state == ToolState::Running)
    });
    if let Some(tool) = active.next() {
        let label = if chat_batch::is_batch(&tool.name) {
            chat_batch::title(tool)
        } else {
            tool_activity(&tool.name).to_owned()
        };
        let detail = if matches!(
            tool.name.to_ascii_lowercase().as_str(),
            "read"
                | "read_file"
                | "edit"
                | "write"
                | "write_file"
                | "create_file"
                | "str_replace"
                | "str_replace_editor"
                | "patch"
                | "apply_patch"
        ) {
            tool.display
                .activity_detail
                .as_deref()
                .unwrap_or(&tool.display.view.subtitle)
        } else {
            &tool.display.view.subtitle
        };
        let detail = first_line(detail);
        let detail = clip_tool_text(detail, 80).0;
        let extra = active.count();
        let mut activity = label.trim_end_matches('…').to_owned();
        if let Some(count) = chat_batch::known_count(tool) {
            activity.push_str(" · ");
            activity.push_str(&chat_batch::call_count_label(count));
        } else if !detail.is_empty() {
            activity.push_str(" · ");
            activity.push_str(&detail);
        } else if label == "Running a tool…" {
            activity.push_str(" · ");
            activity.push_str(&clip_tool_text(&tool.name, 40).0);
        }
        if extra > 0 {
            activity.push_str(&format!(" (+{extra} active)"));
        }
        activity.push('…');
        return activity;
    }
    match turn.next() {
        Some(message) if message.streaming && message.role == ChatRole::Thinking => "Thinking…",
        Some(message) if message.streaming && message.role == ChatRole::Assistant => {
            "Writing a response…"
        }
        _ => "Working…",
    }
    .to_owned()
}

fn chat_activity_tooltip(messages: &[Arc<ChatMessage>]) -> String {
    let tools: Vec<_> = messages
        .iter()
        .rev()
        .take_while(|message| message.role != ChatRole::User)
        .filter_map(|message| {
            message
                .tool
                .as_ref()
                .filter(|tool| tool.state == ToolState::Running)
        })
        .collect();
    if tools.is_empty() {
        return chat_activity(messages);
    }
    tools
        .iter()
        .take(10)
        .map(|tool| {
            if chat_batch::is_batch(&tool.name) {
                return chat_batch::activity_details(tool);
            }
            let detail = tool
                .display
                .activity_detail
                .as_deref()
                .filter(|_| {
                    matches!(
                        tool_activity(&tool.name),
                        "Reading files…" | "Editing files…"
                    )
                })
                .unwrap_or(&tool.display.view.subtitle);
            let detail = clip_tool_text(first_line(detail), 300).0;
            if detail.is_empty() {
                format!(
                    "{} · {}",
                    tool_activity(&tool.name).trim_end_matches('…'),
                    tool.name
                )
            } else {
                format!(
                    "{} · {}",
                    tool_activity(&tool.name).trim_end_matches('…'),
                    detail
                )
            }
        })
        .chain((tools.len() > 10).then(|| format!("And {} more active tools", tools.len() - 10)))
        .collect::<Vec<_>>()
        .join("\n")
}

fn tool_activity(name: &str) -> &'static str {
    match name.to_ascii_lowercase().as_str() {
        "batch" => "Running tools…",
        "read" | "read_file" | "cat" => "Reading files…",
        "edit" | "write" | "write_file" | "create_file" | "str_replace" | "str_replace_editor"
        | "patch" | "apply_patch" => "Editing files…",
        "grep" | "glob" | "ast_grep" | "search" | "rg" | "find" | "list" | "ls" | "list_dir" => {
            "Searching files…"
        }
        "bash" | "shell" | "sh" | "command" | "execute" | "exec" | "eval" | "run"
        | "run_command" | "terminal" => "Running commands…",
        "web_search" | "websearch" | "search_web" | "web_fetch" | "webfetch" | "fetch"
        | "browser" => "Browsing the web…",
        "task" | "agent" | "subagent" | "delegate" | "spawn_agent" | "spawn_subagent" => {
            "Working with subagents…"
        }
        _ => "Running a tool…",
    }
}

#[cfg(test)]
mod chat_activity_tests {
    use super::*;

    #[test]
    fn activity_tracks_current_turn_and_parallel_tools() {
        use agent_bridge::AgentEvent;
        let mut messages = vec![Arc::new(ChatMessage::new(ChatRole::User, "hello".into()))];
        assert_eq!(chat_activity(&messages), "Working…");
        push_chat_event(&mut messages, AgentEvent::Thinking("hmm".into()));
        assert_eq!(chat_activity(&messages), "Thinking…");
        push_chat_event(
            &mut messages,
            AgentEvent::ToolStart {
                id: Some("1".into()),
                name: "read".into(),
                input: r#"{"path":"src/main.rs"}"#.into(),
            },
        );
        assert_eq!(chat_activity(&messages), "Reading files · src/main.rs…");
        push_chat_event(
            &mut messages,
            AgentEvent::ToolStart {
                id: Some("2".into()),
                name: "edit".into(),
                input: r#"{"path":"src/theme.rs"}"#.into(),
            },
        );
        assert_eq!(
            chat_activity(&messages),
            "Editing files · src/theme.rs (+1 active)…"
        );
        assert_eq!(
            chat_activity_tooltip(&messages),
            "Editing files · src/theme.rs\nReading files · src/main.rs"
        );
        push_chat_event(
            &mut messages,
            AgentEvent::ToolEnd {
                id: Some("1".into()),
                name: "read".into(),
                output: String::new(),
                failed: false,
            },
        );
        assert_eq!(chat_activity(&messages), "Editing files · src/theme.rs…");
        messages.push(Arc::new(ChatMessage::new(ChatRole::User, "next".into())));
        assert_eq!(chat_activity(&messages), "Working…");
        push_chat_event(&mut messages, AgentEvent::Text("answer".into()));
        assert_eq!(chat_activity(&messages), "Writing a response…");
    }
}

fn supported_thinking_effort(level: &str) -> bool {
    matches!(
        level,
        "auto" | "inherit" | "low" | "medium" | "high" | "xhigh" | "max"
    )
}

fn reasoning_effort_label(level: &str) -> &str {
    match level {
        "off" => "Off",
        "minimal" => "Minimal",
        "low" => "Light",
        "medium" => "Medium",
        "high" => "High",
        "xhigh" => "Extra high",
        "max" => "Maximum",
        _ => level,
    }
}

#[derive(Default)]
struct AgentChecklist {
    list: Option<embedded::task_list::TaskList>,
    dismissal: Option<gpui::Task<()>>,
    scroll: gpui::ScrollHandle,
    browsing: bool,
}

struct PaneChat {
    /// Retained render boundary: token delivery never invalidates the app shell.
    view: std::cell::RefCell<Option<Entity<AgentChatView>>>,
    focused_scrollbar: std::cell::RefCell<Option<Entity<FocusedChatScrollbar>>>,
    view_visible: std::cell::Cell<bool>,
    worker_view: Option<WorkerView>,
    active: bool,
    info_open: bool,
    bridge: Option<ModelBridge>,
    bridge_model: Option<agent_auth::AgentModel>,

    bridge_resume: Option<String>,
    bridge_needs_context: bool,
    cwd: Option<PathBuf>,
    messages: Vec<Arc<ChatMessage>>,
    running: bool,
    checklist: AgentChecklist,
    requests: std::collections::VecDeque<agent_interaction::Request>,
    follow_ups: std::collections::VecDeque<String>,
    follow_ups_paused: bool,
    follow_ups_collapsed: bool,
    recovery: Option<String>,
    retry_prompt: Option<String>,
    workspace_override: Option<PathBuf>,
    /// Native agent lifecycle, independent of the pane's hidden shell.
    status: SessionStatus,
    /// Completed turns in this conversation.
    completed_turns: u64,
    usage: Option<embedded::AgentUsage>,
    usage_label: SharedString,
    usage_detail: SharedString,
    terminal_draft: String,
    agent_draft: String,
    /// Virtualized transcript state. Only rows near the viewport are built.
    list_state: ListState,
    list_rows: std::cell::Cell<usize>,
    list_key: std::cell::Cell<u64>,
    row_cache: std::rc::Rc<std::cell::RefCell<ChatRowCache>>,
    active_dirty: std::cell::Cell<bool>,
    activity_dirty: std::cell::Cell<bool>,
    dirty_messages: std::cell::RefCell<HashSet<usize>>,
    scroll_handler_installed: std::cell::Cell<bool>,
    auth_refresh_pending: bool,
    auth: Option<AuthModal>,
    selected_model: Option<agent_auth::AgentModel>,
    permission_mode: agent_bridge::PermissionMode,
    first_response_provider: Option<String>,
    /// Retained for compatibility with older saved workspaces.
    model_explicit: bool,
    agent_title: Option<String>,
    prompt_title: Option<String>,
    conversation_key: String,
    legacy_models: Vec<workspace_state::SavedModelChat>,
    fast_mode: bool,
    thinking_override: Option<String>,
    thinking_by_model: HashMap<String, String>,
    pub autoscroll: bool,
    expanded_tool_groups: HashMap<String, HashSet<usize>>,
    shob_session_id: Option<String>,
    conversation: Option<conversations::Log>,
    startup_error: Option<String>,
}

